import re
def parse_duration(text: str) -> int:
    text = text.strip()
    if not text:
        raise ValueError("Invalid duration")
    matches = re.findall(r'(\d+)([hms])', text)
    if ''.join(num + unit for num, unit in matches) != text:
        raise ValueError("Invalid duration")
    unit_order = {'h': 0, 'm': 1, 's': 2}
    prev_idx = -1
    total_seconds = 0
    multipliers = {'h': 3600, 'm': 60, 's': 1}
    for num_str, unit in matches:
        idx = unit_order[unit]
        if idx <= prev_idx:
            raise ValueError("Units out of order or repeated")
        prev_idx = idx
        total_seconds += int(num_str) * multipliers[unit]
    return total_seconds

import re
def parse_duration(text: str) -> int:
    match = re.match(r'^\s*(?:(\d+)\s*h)?\s*(?:(\d+)\s*m)?\s*(?:(\d+)\s*s)?\s*$', text)
    if match is None:
        raise ValueError("Invalid duration format")
    h, m, s = match.groups()
    if h is None and m is None and s is None:
        raise ValueError("Invalid duration format")
    total = 0
    if h:
        total += int(h) * 3600
    if m:
        total += int(m) * 60
    if s:
        total += int(s)
    return total

import re
def parse_duration(text: str) -> int:
    cleaned = re.sub(r'\s+', '', text).lower()
    if not cleaned:
        raise ValueError("Empty duration")
    pattern = r'^(\d+d)?(\d+h)?(\d+m)?(\d+s)?$'
    match = re.match(pattern, cleaned)
    if not match:
        raise ValueError("Invalid duration format")
    total = 0
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    for i, u in enumerate('dhms'):
        part = match.group(i + 1)
        if part:
            num = int(part[:-1])
            total += num * units[u]
    return total

