def parse_duration(text: str) -> int:
    text = text.strip().lower()
    if not text:
        raise ValueError("empty duration")
    pattern = r'^(?:(\d+)\s*d)?\s*(?:(\d+)\s*h)?\s*(?:(\d+)\s*m)?\s*(?:(\d+)\s*s)?$'
    match = re.match(pattern, text)
    if not match:
        raise ValueError("invalid duration format")
    d, h, m, s = match.groups()
    total_seconds = 0
    if d:
        total_seconds += int(d) * 86400
    if h:
        total_seconds += int(h) * 3600
    if m:
        total_seconds += int(m) * 60
    if s:
        total_seconds += int(s)
    return total_seconds

import re

def parse_duration(text: str) -> int:
    text = text.strip()
    match = re.match(r'^(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$', text)
    if not match or all(g is None for g in match.groups()):
        raise ValueError("Invalid duration")
    days, hours, minutes, seconds = match.groups()
    total_seconds = 0
    if days:
        total_seconds += int(days) * 86400
    if hours:
        total_seconds += int(hours) * 3600
    if minutes:
        total_seconds += int(minutes) * 60
    if seconds:
        total_seconds += int(seconds)
    return total_seconds

import re
def parse_duration(text: str) -> int:
    text = ''.join(text.split())
    if not text:
        raise ValueError("Invalid duration")
    pattern = r'(\d+)([dhms])'
    matches = re.findall(pattern, text)
    if not matches or ''.join(num + unit for num, unit in matches) != text:
        raise ValueError("Invalid duration")
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total = 0
    last_idx = -1
    order = 'dhms'
    for num, unit in matches:
        idx = order.index(unit)
        if idx <= last_idx:
            raise ValueError("Units out of order or repeated")
        total += int(num) * units[unit]
        last_idx = idx
    return total

import re

def parse_duration(text: str) -> int:
    stripped = text.strip()
    if not stripped:
        raise ValueError("Invalid duration")
    pattern = r'^\s*(?:(\d+)d)?\s*(?:(\d+)h)?\s*(?:(\d+)m)?\s*(?:(\d+)s)?\s*$'
    match = re.match(pattern, stripped.lower())
    if not match:
        raise ValueError("Invalid duration")
    days, hours, mins, secs = match.groups()
    if not any([days, hours, mins, secs]):
        raise ValueError("Invalid duration")
    total = 0
    if days:
        total += int(days) * 86400
    if hours:
        total += int(hours) * 3600
    if mins:
        total += int(mins) * 60
    if secs:
        total += int(secs)
    return total

import re

def parse_duration(text: str) -> int:
    pattern = re.compile(r'^\s*(?:(\d+)d)?\s*(?:(\d+)h)?\s*(?:(\d+)m)?\s*(?:(\d+)s)?\s*$')
    match = pattern.match(text)
    if not match:
        raise ValueError('Invalid duration string')
    groups = match.groups()
    if all(g is None for g in groups):
        raise ValueError('Invalid duration string')
    factors = [86400, 3600, 60, 1]
    total = 0
    for val, factor in zip(groups, factors):
        if val is not None:
            total += int(val) * factor
    return total

def chunk(items: list, size: int) -> list[list]:
    if size < 1:
        raise ValueError("size must be a positive integer")
    result = []
    step = (len(items) // size) * size
    for i in range(0, step, size):
        result.append(items[i:i + size])
    return result

def chunk(items: list, size: int) -> list[list]:
    if size < 1:
        raise ValueError
    return [items[i:i + size] for i in range(0, len(items), size) if i + size <= len(items)]

def chunk(items: list, size: int) -> list[list]:
    if size < 1:
        raise ValueError("size must be a positive integer")
    return [items[i:i+size] for i in range(0, len(items) - len(items) % size, size)]

def chunk(items: list, size: int) -> list[list]:
    if not isinstance(size, int) or size <= 0:
        raise ValueError
    return [items[i:i + size] for i in range(0, (len(items) // size) * size, size)]

